{
  "project": "cadi-alfa",
  "module": "sistemas_medidores",
  "description": "Módulo M3: Sistemas de Medidores. Gestiona la aplicación de deltas, decaimiento pasivo, interdependencias y comprobación de umbrales para los 6 medidores (influencia, relacional, reputación, coherencia, recursos, aguante). Basado en el documento de arquitectura y specs/engine/medidores.schema.yaml.",
  "functions": [
    {
      "name": "aplicar_delta_a_medidor",
      "signature": "pub fn aplicar_delta_a_medidor(medidor: &mut u8, delta: i8, umbral_bajo: u8, umbral_alto: u8) -> (u8, i8)",
      "description": "Aplica un delta a un medidor, respetando los límites (0-100). Devuelve el nuevo valor y la tendencia resultante.",
      "examples": [
        "let (nuevo_valor, nueva_tendencia) = aplicar_delta_a_medidor(&mut influencia, 10, 20, 80);"
      ]
    },
    {
      "name": "aplicar_decaimiento_pasivo",
      "signature": "pub fn aplicar_decaimiento_pasivo(meters: &mut PlayerMeters)",
      "description": "Reduce cada medidor según su tendencia (ej: -1 por jornada si tendencia < 0). Usa saturating_sub para evitar negativos."
    },
    {
      "name": "aplicar_interdependencias",
      "signature": "pub fn aplicar_interdependencias(meters: &mut PlayerMeters)",
      "description": "Ajusta medidores según reglas de interdependencia (ej: si influencia sube, reputación puede bajar). Usa el archivo interdependencias.yaml para las reglas."
    },
    {
      "name": "comprobar_umbrales_medidores",
      "signature": "pub fn comprobar_umbrales_medidores(meters: &PlayerMeters) -> Vec<String>",
      "description": "Comprueba si algún medidor ha cruzado sus umbrales (bajo o alto). Devuelve una lista de alertas.",
      "examples": [
        "let alertas = comprobar_umbrales_medidores(&player.meters);"
      ]
    }
  ],
  "tests": [
    "#[test] fn test_aplicar_delta_a_medidor_respeta_limites() { let mut val = 50; let (nuevo, _) = aplicar_delta_a_medidor(&mut val, 60, 0, 100); assert_eq!(nuevo, 100); }",
    "#[test] fn test_aplicar_delta_a_medidor_no_excede_minimo() { let mut val = 30; let (nuevo, _) = aplicar_delta_a_medidor(&mut val, -40, 0, 100); assert_eq!(nuevo, 0); }",
    "#[test] fn test_aplicar_decaimiento_pasivo_reduce_medidores() { let mut meters = PlayerMeters { influencia_valor: 50, influencia_tendencia: -1, ..Default::default() }; aplicar_decaimiento_pasivo(&mut meters); assert_eq!(meters.influencia_valor, 49); }",
    "#[test] fn test_comprobar_umbrales_detecta_bajo() { let meters = PlayerMeters { influencia_valor: 10, influencia_umbral_bajo: 20, ..Default::default() }; let alertas = comprobar_umbrales_medidores(&meters); assert!(alertas.contains(&String::from(\"med_influencia bajo umbral\"))); }"
  ],
  "dependencies": [
    "serde"
  ],
  "notes": "Ubicar en /media/alvaro/service/project-stack/cadi-alfa/repo/rust/crates/game_core/src/sistemas_medidores.rs. Importar: use crate::player_state::PlayerMeters. Usar u8 para valores de medidores y i8 para deltas/tendencias. Las interdependencias se cargarán desde content/cadiz/config/interdependencias.yaml en una implementación futura."
}
